import React, { useState } from 'react';
import axios from 'axios';
import './Prediction.css';

function Prediction() {
  const [formData, setFormData] = useState({
    year: new Date().getFullYear(),
    gender: 'Female',
    age: 30,
    location: 'Urban',
    race: 'Caucasian',
    hypertension: 0,
    heart_disease: 0,
    smoking_history: 'never',
    bmi: 25.0,
    hbA1c_level: 5.0,
    blood_glucose_level: 100
  });
  
  const [prediction, setPrediction] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');

  const validateField = (name, value) => {
    const newErrors = {...errors};
    
    switch (name) {
      case 'age':
        if (value < 0 || value > 120) newErrors.age = 'Age must be between 0 and 120';
        else delete newErrors.age;
        break;
      case 'bmi':
        if (value < 10 || value > 50) newErrors.bmi = 'BMI must be between 10 and 50';
        else delete newErrors.bmi;
        break;
      case 'hbA1c_level':
        if (value < 3 || value > 15) newErrors.hbA1c_level = 'HbA1c must be between 3% and 15%';
        else delete newErrors.hbA1c_level;
        break;
      case 'blood_glucose_level':
        if (value < 50 || value > 300) newErrors.blood_glucose_level = 'Glucose level must be between 50 and 300 mg/dL';
        else delete newErrors.blood_glucose_level;
        break;
      default:
        break;
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    const processedValue = type === 'checkbox' ? (checked ? 1 : 0) : 
                         name === 'age' || name === 'bmi' || name === 'hbA1c_level' || name === 'blood_glucose_level' ? 
                         parseFloat(value) : value;
    
    setFormData(prev => ({
      ...prev,
      [name]: processedValue
    }));
    
    if (type !== 'checkbox') {
      validateField(name, processedValue);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setApiError('');
    
    // Validate all fields
    let isValid = true;
    const fieldsToValidate = ['age', 'bmi', 'hbA1c_level', 'blood_glucose_level'];
    fieldsToValidate.forEach(field => {
      if (!validateField(field, formData[field])) {
        isValid = false;
      }
    });
    
    if (!isValid || Object.keys(errors).length > 0) {
      setApiError('Please fix all validation errors');
      return;
    }
    
    setIsLoading(true);
    
    try {
      const response = await axios.post('http://localhost:8000/predict', formData);
      setPrediction(response.data);
    } catch (error) {
      console.error("Prediction error:", error);
      setApiError(error.response?.data?.detail || 'Failed to get prediction. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="prediction-container">
      <div className="prediction-header">
        <h2>Diabetes Risk Assessment</h2>
        <p>Fill in your health information to assess your diabetes risk</p>
      </div>
      
      <form onSubmit={handleSubmit} className="prediction-form">
        <div className="form-grid">
          <div className="form-group">
            <label htmlFor="age">Age:</label>
            <input
              id="age"
              type="number"
              name="age"
              value={formData.age}
              onChange={handleChange}
              min="0"
              max="120"
              step="1"
              className={errors.age ? 'error' : ''}
              required
            />
            {errors.age && <span className="error-message">{errors.age}</span>}
          </div>
          
          <div className="form-group">
            <label htmlFor="gender">Gender:</label>
            <select
              id="gender"
              name="gender"
              value={formData.gender}
              onChange={handleChange}
              className="form-select"
              required
            >
              <option value="Female">Female</option>
              <option value="Male">Male</option>
              <option value="Other">Other</option>
            </select>
          </div>
          
          <div className="form-group">
            <label htmlFor="race">Race/Ethnicity:</label>
            <select
              id="race"
              name="race"
              value={formData.race}
              onChange={handleChange}
              className="form-select"
              required
            >
              <option value="AfricanAmerican">African American</option>
              <option value="Asian">Asian</option>
              <option value="Caucasian">Caucasian</option>
              <option value="Hispanic">Hispanic</option>
              <option value="Other">Other</option>
            </select>
          </div>
          
          <div className="form-group">
            <label htmlFor="location">Location:</label>
            <select
              id="location"
              name="location"
              value={formData.location}
              onChange={handleChange}
              className="form-select"
              required
            >
              <option value="Urban">Urban</option>
              <option value="Suburban">Suburban</option>
              <option value="Rural">Rural</option>
            </select>
          </div>
          
          <div className="form-group">
            <label htmlFor="bmi">BMI:</label>
            <input
              id="bmi"
              type="number"
              name="bmi"
              value={formData.bmi}
              onChange={handleChange}
              min="10"
              max="50"
              step="0.1"
              className={errors.bmi ? 'error' : ''}
              required
            />
            {errors.bmi && <span className="error-message">{errors.bmi}</span>}
          </div>
          
          <div className="form-group">
            <label htmlFor="hbA1c_level">HbA1c Level (%):</label>
            <input
              id="hbA1c_level"
              type="number"
              name="hbA1c_level"
              value={formData.hbA1c_level}
              onChange={handleChange}
              min="3"
              max="15"
              step="0.1"
              className={errors.hbA1c_level ? 'error' : ''}
              required
            />
            {errors.hbA1c_level && <span className="error-message">{errors.hbA1c_level}</span>}
          </div>
          
          <div className="form-group">
            <label htmlFor="blood_glucose_level">Blood Glucose Level (mg/dL):</label>
            <input
              id="blood_glucose_level"
              type="number"
              name="blood_glucose_level"
              value={formData.blood_glucose_level}
              onChange={handleChange}
              min="50"
              max="300"
              step="1"
              className={errors.blood_glucose_level ? 'error' : ''}
              required
            />
            {errors.blood_glucose_level && <span className="error-message">{errors.blood_glucose_level}</span>}
          </div>
          
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                name="hypertension"
                checked={formData.hypertension === 1}
                onChange={handleChange}
                className="checkbox-input"
              />
              <span className="checkbox-custom"></span>
              Hypertension
            </label>
          </div>
          
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                name="heart_disease"
                checked={formData.heart_disease === 1}
                onChange={handleChange}
                className="checkbox-input"
              />
              <span className="checkbox-custom"></span>
              Heart Disease
            </label>
          </div>
          
          <div className="form-group">
            <label htmlFor="smoking_history">Smoking History:</label>
            <select
              id="smoking_history"
              name="smoking_history"
              value={formData.smoking_history}
              onChange={handleChange}
              className="form-select"
              required
            >
              <option value="never">Never smoked</option>
              <option value="former">Former smoker</option>
              <option value="current">Current smoker</option>
              <option value="not current">Not current smoker</option>
              <option value="ever">Ever smoked</option>
            </select>
          </div>
        </div>
        
        <div className="form-actions">
          <button
            type="submit"
            disabled={isLoading}
            className="submit-btn"
          >
            {isLoading ? (
              <>
                <span className="spinner"></span> Predicting...
              </>
            ) : (
              'Assess Diabetes Risk'
            )}
          </button>
        </div>
      </form>
      
      {apiError && <div className="api-error">{apiError}</div>}
      
      {prediction && (
        <div className={`prediction-result ${prediction.prediction ? 'high-risk' : 'low-risk'}`}>
          <h3>Assessment Results</h3>
          <div className="result-metric">
            <span className="metric-label">Risk Level:</span>
            <span className="metric-value">{prediction.interpretation}</span>
          </div>
          <div className="result-metric">
            <span className="metric-label">Probability:</span>
            <span className="metric-value">{(prediction.probability * 100).toFixed(1)}%</span>
          </div>
          <div className="recommendation">
            {prediction.prediction ? (
              <>
                <p>Our assessment indicates a high risk of diabetes.</p>
                <p>We recommend consulting with a healthcare professional for further evaluation and guidance.</p>
              </>
            ) : (
              <>
                <p>Our assessment indicates a low risk of diabetes.</p>
                <p>Maintain healthy habits including regular exercise and balanced nutrition to keep your risk low.</p>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default Prediction;
